/* Portable specifications and reproducible R script; never executes generated code. */
(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.AtlasQueryArtifacts=api})(typeof globalThis!=='undefined'?globalThis:this,function(){
'use strict';
function chartSpec(result){const series=result.series||[result];return {kind:'line',x:'year',y:'value',unit:result.unit,title:`${result.indicator} · ${result.period.from}–${result.period.to}`,series:series.map(s=>({label:s.geography.name,points:s.values.map(({year,value})=>({year,value}))})),source:result.source,reference:result.reference,warnings:result.warnings}}
function mapSpec(map){if(!map.geometryFile)throw Error('Malha não definida para este recorte');return {kind:'choropleth',year:map.year,unit:map.unit,geometryFile:map.geometryFile,joinKey:'code',values:map.values,source:map.source,reference:map.reference,warnings:map.warnings}}
function rCode(result){const series=result.series||[result],dataset=series[0]?.dataset;if(dataset==='ibge-aquaculture'){if(series.some(s=>s.indicator!=='production_t'||s.geography.type!=='uf'))throw Error('R incompatível com este recorte');const codes=series.map(s=>s.geography.code),from=result.period.from,to=result.period.to,quoted=codes.map(x=>`"${x}"`).join(', ');return `# Fonte: IBGE PPM / SIDRA 3940; ausentes permanecem NA.\nurl <- "https://explorador-pesca-aquicultura.ph-magmelo.chatgpt.site/downloads/ibge-aquicultura-uf-2013-2024.csv"\ndados <- read.csv(url, fileEncoding = "UTF-8-BOM", check.names = FALSE)\nufs <- c(${quoted}); anos <- ${from}:${to}\nrecorte <- subset(dados, codigo_uf %in% ufs & ano %in% anos)\nresultado <- merge(expand.grid(ano=anos, codigo_uf=ufs), aggregate(producao_t ~ ano + codigo_uf, recorte, sum), all.x=TRUE)\nprint(resultado)\n`;}if(dataset==='mdic-trade'){const from=result.period.from,to=result.period.to;return `# Fonte: MDIC Comex Stat; cópia versionada do Atlas.\n# Indicador: ${result.indicator}; unidade: ${result.unit}.\n# 2026 é parcial quando incluído; ausência permanece NA.\ntrade <- read.csv("trade.csv", check.names=FALSE)\ntrade$valor <- ifelse(trade$indicador == "fob_usd", trade$valor_fob_usd, trade$peso_liquido_kg/1000)\nrecorte <- subset(trade, ano >= ${from} & ano <= ${to})\nresultado <- aggregate(valor ~ ano + fluxo, recorte, sum)\nprint(resultado)\n`;}if(dataset==='ibge-municipal'){return `# Fonte: IBGE PPM / SIDRA 3940; ano municipal: 2024.\n# Indicador: production_t; ausentes permanecem NA.\nmunicipal <- read.csv("municipal.csv", check.names=FALSE)\nrecorte <- subset(municipal, ano == 2024)\nresultado <- aggregate(producao_t ~ codigo_municipio + uf, recorte, sum)\nprint(resultado)\n`;}throw Error('R indisponível para este dataset');}
return Object.freeze({chartSpec,mapSpec,rCode});
});
